import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"The frozen public API — the eqsat (substrate) slice","description":"","frontmatter":{},"headers":[],"relativePath":"eqsat/reference/frozen-api.md","filePath":"vendored/eqsat/reference/frozen-api.md"}`),a={name:`eqsat/reference/frozen-api.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<div class="warning custom-block"><p class="custom-block-title">Vendored slice — do not edit here</p><p>Synced from <code>graphopt:docs/public_api.md</code> @ <code>ed89ead</code> — the phase-1 frozen manifest (<code>API_VERSION = &quot;0.1.0&quot;</code>). This page is the <strong>eqsat slice</strong>: the substrate rows of the contract, landed at the plan-0032 phase-4 split. The manifest upstream carries all three slices; the game rows are <a href="/docs/gamekit/reference/frozen-api.html">gamekit&#39;s</a> and the domain rows are <a href="/docs/graphopt/reference/frozen-api.html">graphopt&#39;s</a>.</p></div><h1 id="the-frozen-public-api-—-the-eqsat-substrate-slice" tabindex="-1">The frozen public API — the eqsat (substrate) slice <a class="header-anchor" href="#the-frozen-public-api-—-the-eqsat-substrate-slice" aria-label="Permalink to “The frozen public API — the eqsat (substrate) slice”">​</a></h1><blockquote><p><strong>Version:</strong> <code>from mlopt_core import API_VERSION</code>. The <code>0.x</code> series covered the monorepo contract; with the split landed, each repo versions its own slice — the rows below are the ones <code>handl-lang/eqsat</code> must not break.</p></blockquote><ul><li><strong>Frozen</strong> — a name in the table below. Renaming, retyping, or re-homing it without an <code>API_VERSION</code> major bump is a contract break.</li><li><strong>Public, unfrozen</strong> — any other name in a module&#39;s <code>__all__</code>.</li><li><strong>Internal</strong> — everything else, including underscore compat re-exports (<code>egraph._term_match</code>, <code>cost._memo_dispatch</code>, …). Reachable is not public.</li></ul><h2 id="substrate-contracts" tabindex="-1">Substrate contracts <a class="header-anchor" href="#substrate-contracts" aria-label="Permalink to “Substrate contracts”">​</a></h2><table tabindex="0"><thead><tr><th>Contract</th><th>Canonical location</th><th>Frozen surface</th></tr></thead><tbody><tr><td>Term IR</td><td><code>mlopt_core.ir</code></td><td><code>IR</code>, <code>Op</code> (incl. <code>Op.make</code>), <code>Var</code>, <code>Param</code>, <code>Const</code>, <code>TensorType</code>, <code>op_repr</code>, <code>op_repr_dag</code>, <code>term_to_data</code>, <code>term_from_data</code></td></tr><tr><td>E-graph engine</td><td><code>mlopt_core.egraph</code></td><td><code>EGraph</code>, <code>ENode</code>, <code>EClass</code>, <code>UnionFind</code>, <code>Rewrite</code></td></tr><tr><td><code>EGraph</code> protocol</td><td><code>mlopt_core.egraph.EGraph</code></td><td><code>add_term(term) -&gt; eid</code>, <code>find(eid)</code>, <code>rebuild(classes=None)</code>, <code>extract_best(eid, cost_fn, **kw)</code>, <code>certificate(src, dst, root_eid=...)</code>, <strong><code>run(rules, root_eid, *, max_iterations=100, max_nodes=100_000, rule_budgets=None, stop=&quot;fixed_point&quot;, patience=3, cost_fn=None, policy=None) -&gt; stats</code></strong> — <code>stats</code> carries <code>stop</code>, <code>n_enodes</code>, <code>n_classes</code>, <code>rule_fires</code>, <code>rule_budgets</code></td></tr><tr><td>Certificates</td><td><code>mlopt_core.egraph</code></td><td><code>Certificate</code>, <code>CertStep</code>, <code>ProofEdge</code>, <code>CertificateVerificationError</code>, <code>cert_to_data</code>, <code>cert_from_data</code>, <strong><code>verify_certificate(term, cert, *, strict=False)</code></strong> — the standalone derivation replay</td></tr><tr><td>DAG pricing</td><td><code>mlopt_core.cost</code></td><td><strong><code>dag_cost(term, cost_fn, memo=None)</code></strong> — the shared-subtree-honest price; plus the shipped models <code>count_cost</code>, <code>flops_cost</code>, <code>param_bytes_cost</code>, <code>param_bytes_cost_for</code>, <code>backend_cost</code>, <code>executor_cost_for</code>, <code>fused_cost_for</code>, <code>lowering_aware_cost_for</code>, <code>depth_cost</code>, <code>depth_cost_for</code>, <code>roofline_cost</code>, <code>roofline_cost_for</code>, <code>launch_aware_cost</code>, <code>fusion_regions</code>, <code>fusion_member_key</code>, <code>CostModel</code>, <code>LOWERINGS</code></td></tr><tr><td>Ports</td><td><code>mlopt_core.ports</code></td><td><strong><code>Sink</code></strong> (<code>lower</code>/<code>verify</code>/<code>executors</code> on top of <strong><code>Capabilities</code></strong>&#39;s <code>supported_ops</code>/<code>ops</code>), <strong><code>Source</code></strong>, <strong><code>Engine</code></strong> (the <code>engine=</code> contract below), <code>Composer</code>, <code>Executor</code>, <code>ExecutorSpec</code>, <code>Runner</code>, <code>Meter</code>, <code>Verifier</code>, <code>VerifyResult</code>, <code>CostFn</code>, <code>Criterion</code>, <code>Policy</code>, <code>Strategy</code>, <code>TaskMetric</code>, <code>PerformanceModel</code>, <code>Profiler</code>, <code>OpRegistry</code>, <code>RuleSetLike</code>, <code>RuleLike</code>, <code>RuleSetProvider</code>, <code>Binding</code>, <code>TimingResult</code>, <code>signature_conforms</code></td></tr><tr><td>Law machinery</td><td><code>mlopt_core.laws</code></td><td><code>RuleSet</code>, <code>preset</code>, <code>DEFAULT</code>, <code>FULL</code>, <code>SYMMETRY</code>, <code>ALL_RULES</code>, <code>tags</code>, <code>provenance</code> — the <em>names</em> are frozen; the <strong>bank contents</strong> (<code>ALL_RULES</code> membership, <code>MACHINE_SHIPPED</code> rows) are each domain repo&#39;s data, not the substrate&#39;s contract</td></tr><tr><td>Provenance registry</td><td><code>mlopt_core.laws.provenance</code></td><td><code>MACHINE_SHIPPED</code>, <code>MACHINE_STORED</code>, <code>MACHINE_LAWS</code>, <code>law_provenance(rule) -&gt; &quot;machine&quot; | &quot;human&quot;</code></td></tr><tr><td>The pipeline</td><td><code>mlopt_orchestrator</code></td><td><code>Optimizer</code>, <strong><code>search(model, x, *, source, capabilities=None, criteria=None, cost_fn=None, rules=None, engine=None, policy=None, …) -&gt; SearchResult</code></strong>, <code>lower</code>, <code>SearchResult</code>, <code>LowerResult</code>, <code>Backend</code>, <code>discover_alternatives</code>, <code>DEFAULT_RULES</code>, <code>OptimizationResourceError</code>, strategies <code>Monolithic</code>/<code>Compositional</code>/<code>Autotuned</code>, runners <code>IdentityRunner</code>/<code>ChainedRunner</code>/<code>runner_candidate</code>, criteria family (<code>Criterion</code>, <code>Criteria</code>, <code>Blend</code>, <code>criteria_cost</code>, <code>peak_bytes_cost</code>, <code>LatencyCriterion</code>, <code>MemoryCriterion</code>, <code>FlopsCriterion</code>, <code>DepthCriterion</code>, <code>CompiledCriterion</code>, <code>PredictedCriterion</code>), <code>delivered_cost_for</code>, <code>structural_key</code></td></tr><tr><td><code>engine=</code></td><td><code>search</code>/<code>Optimizer</code> kwarg</td><td>An <code>Engine</code>-port value — instance, class, or zero-arg factory. Engines are <strong>never auto-detected</strong>; <code>stats[&quot;engine&quot;]</code> records which ran (<code>&quot;python&quot;</code> reference default, <code>&quot;native&quot;</code> for <code>mlopt_native.NativeEngine</code>). The port covers the <em>search</em> only — certificates and the non-local passes are Python-engine capabilities</td></tr></tbody></table><h2 id="boundary-notes" tabindex="-1">Boundary notes <a class="header-anchor" href="#boundary-notes" aria-label="Permalink to “Boundary notes”">​</a></h2><ul><li><strong><code>mlopt_native</code></strong> is an opt-in engine behind <code>engine=</code>, not a frozen import path: it is excluded from the uv workspace, so the contract binds the <code>Engine</code> <em>port</em>, not the package.</li><li><strong>Registry contents vs registry shape</strong>: <code>ALL_RULES</code> / <code>MACHINE_SHIPPED</code> contents are <em>data</em> — the names and access functions are frozen, the rows are each consuming repo&#39;s business.</li></ul><p>The full manifest — including the domain-side rows — is <a href="https://github.com/handl-lang/graphopt/blob/main/docs/public_api.md" target="_blank" rel="noreferrer"><code>docs/public_api.md</code></a> upstream.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};